// Extract contract-specific fields
const text = ($json.text || '').toLowerCase();
const id_number = $json.id_number || '';

// Contract-specific extraction patterns
const patterns = {
  borrower_name: /borrower[\s\-]*name[\s\-]*:?[\s\-]*([^\n]+)/i,
  lender_name: /lender[\s\-]*name[\s\-]*:?[\s\-]*([^\n]+)/i,
  loan_amount: /(?:loan|principal)[\s\-]*amount[\s\-]*:?[\s\-]*\$?([0-9,]+(?:\.\d{2})?)/i,
  interest_rate: /(?:interest|rate)[\s\-]*:?[\s\-]*([0-9]+(?:\.\d+)?)[\s\-]*%/i,
  term_months: /(?:term|duration)[\s\-]*:?[\s\-]*([0-9]+)[\s\-]*(?:months?|years?)/i
};

const extracted = {};

// Extract each field
Object.entries(patterns).forEach(([key, pattern]) => {
  const match = text.match(pattern);
  if (match) {
    extracted[key] = match[1].trim();
  }
});

// Add metadata
const result = {
  job_id: $json.job_id || ("jb_" + Date.now()),
  document_type: 'CONTRACT',
  id_number: id_number,
  extraction_confidence: 0.85,
  extracted_at: new Date().toISOString(),
  values: extracted
};

return [{ json: result }];
